from itertools import permutations

singers = ("K", "L", "T", "W", "Y", "Z")
recorded = {"K", "L"}
valid = []

for order in permutations(singers):
    p = {s: i + 1 for i, s in enumerate(order)}
    if order[3] in recorded:
        continue
    if order[4] not in recorded:
        continue
    if not (p["W"] < p["K"] and p["W"] < p["L"]):
        continue
    if not p["K"] < p["T"]:
        continue
    if not p["Z"] < p["Y"]:
        continue
    if p["Y"] != p["K"] + 1:
        continue
    valid.append(order)

tests = {
    "A": lambda p: p["K"] == 2,
    "B": lambda p: p["T"] == 4,
    "C": lambda p: p["W"] == 3,
    "D": lambda p: p["Y"] == 6,
    "E": lambda p: p["Z"] == 2,
}

possible = []
print("Exhaustive enumeration of all 720 audition orders.")
print("Orders satisfying all rules and the additional condition:", len(valid))
for label, test in tests.items():
    witnesses = [
        order for order in valid
        if test({s: i + 1 for i, s in enumerate(order)})
    ]
    print(f"{label}: {len(witnesses)} qualifying orders")
    if witnesses:
        possible.append(label)
        print("  Witness:", " ".join(witnesses[0]))

print("Expected possible option(s):", ", ".join(possible) or "none")
print("Submitted answer: A")
print("CHECK PASS" if possible == ["A"] else "CHECK FAIL")
